"""Deterministic multi-instrument event replay with resumable snapshots.

This layer adds nothing to the baseline matching semantics: each financial
event (``ADD`` / ``CANCEL`` / ``REPLACE`` and the baseline query events) is
handled by an independent per-symbol :class:`~order_book_engine.engine.Engine`
exactly as the baseline does.  It additionally provides:

* strict per-symbol ``sequence`` streams (gaps and regressions rejected);
* idempotent replay keyed by ``event_id`` over normalized event content;
* per-event results carrying trades and explicit before/after book changes;
* canonical, byte-comparable JSON serialization;
* self-describing, checksummed in-memory snapshots that resume a replay so
  trade ids, trade order and final results are identical to an uninterrupted
  run.

No file is ever read or written here: events, results and snapshots are plain
JSON-compatible Python objects handed to or returned by the public entry
points.  Persistence, if desired, is the caller's responsibility.
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

from .engine import Engine

# --- Replay outcome statuses ------------------------------------------------

ACCEPTED = "ACCEPTED"
"""The event was well formed, in sequence and produced a baseline result."""

REJECTED = "REJECTED"
"""The event was invalid, out of sequence or refused by baseline rules."""

DUPLICATE = "DUPLICATE"
"""A seen ``event_id`` was replayed with byte-identical normalized content."""

# --- Replay rejection codes -------------------------------------------------

INVALID_EVENT = "INVALID_EVENT"
"""Missing fields, illegal values, an unknown envelope/order event type."""

SEQUENCE_GAP = "SEQUENCE_GAP"
"""The symbol's sequence jumped over one or more expected values."""

OUT_OF_ORDER = "OUT_OF_ORDER"
"""The symbol's sequence did not strictly increase."""

EVENT_ID_CONFLICT = "EVENT_ID_CONFLICT"
"""A seen ``event_id`` arrived with different normalized content."""

# --- Snapshot rejection codes ----------------------------------------------

SNAPSHOT_CORRUPT = "SNAPSHOT_CORRUPT"
SNAPSHOT_VERSION_UNSUPPORTED = "SNAPSHOT_VERSION_UNSUPPORTED"
CONFIG_MISMATCH = "CONFIG_MISMATCH"

FORMAT_VERSION = "order-book-replay/1"

# Baseline behaviour fixed by the snapshot configuration summary.  Values are
# sorted so the summary itself is canonical.
_CONFIG: dict[str, object] = {
    "matching": "price-time-priority",
    "engine_state_format": 1,
    "trade_id_start": 1,
    "supported_order_types": ["ICEBERG", "LIMIT", "MARKET"],
    "supported_sides": ["BUY", "SELL"],
    "supported_time_in_force": ["FOK", "GTC", "IOC"],
    "order_event_types": ["ADD", "CANCEL", "REPLACE"],
}

_ENVELOPE_KEYS = frozenset({"event_id", "symbol", "sequence", "type", "event"})


class CanonicalError(ValueError):
    """Raised when an object cannot be represented in canonical JSON."""


class SnapshotError(ValueError):
    """Raised when a snapshot cannot be restored.

    ``code`` is one of :data:`SNAPSHOT_CORRUPT`,
    :data:`SNAPSHOT_VERSION_UNSUPPORTED` or :data:`CONFIG_MISMATCH`.  A failed
    restoration never creates a partially restored replayer.
    """

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


class _Ordered:
    """Total, type-stable ordering wrapper for canonical JSON key sorting."""

    __slots__ = ("value",)

    def __init__(self, value: Any) -> None:
        self.value = value

    def _rank(self) -> tuple[int, Any]:
        value = self.value
        if value is None:
            return (0, 0)
        if isinstance(value, bool):
            return (1, int(value))
        if isinstance(value, (int, float)):
            return (2, value)
        if isinstance(value, str):
            return (3, value)
        if isinstance(value, list):
            return (4, None)
        if isinstance(value, dict):
            return (5, None)
        return (6, repr(value))

    def __lt__(self, other: _Ordered) -> bool:
        rank = self._rank()
        other_rank = other._rank()
        if rank[0] != other_rank[0]:
            return rank[0] < other_rank[0]
        if rank[0] in (4, 5):
            # Containers of different shapes never compare equal; fall back to
            # a stable textual tiebreaker instead of recursing into unordered
            # containers.
            return canonical_dumps(self.value) < canonical_dumps(other.value)
        return rank[1] < other_rank[1]

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, _Ordered):
            return NotImplemented
        return canonical_dumps(self.value) == canonical_dumps(other.value)

    def __hash__(self) -> int:
        return hash(canonical_dumps(self.value))


def canonical_dumps(obj: Any) -> bytes:
    """Serialize *obj* to deterministic, byte-comparable canonical JSON.

    Object keys are sorted by a type-stable total order, compact separators
    are used and non-ASCII characters pass through unescaped, exactly as in the
    baseline replay output.  Identical content always yields identical bytes
    regardless of insertion order.
    """
    return json.dumps(
        _canonicalize(obj),
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")


def _canonicalize(obj: Any) -> Any:
    if obj is None or isinstance(obj, (str, bool, int, float)):
        return obj
    if isinstance(obj, dict):
        return [
            [_canonicalize(_Ordered(key).value), _canonicalize(value)]
            for key, value in sorted(
                ((_Ordered(k), v) for k, v in obj.items()),
                key=lambda item: item[0],
            )
        ]
    if isinstance(obj, (list, tuple)):
        return [_canonicalize(item) for item in obj]
    raise CanonicalError(f"object is not JSON-compatible: {type(obj)!r}")


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _is_int(value: Any) -> bool:
    # ``bool`` is a subclass of ``int`` and is not a sequence number.
    return isinstance(value, int) and not isinstance(value, bool)


def _public_book(engine: Engine) -> dict[str, list[dict[str, int]]]:
    bids, asks = engine.snapshot()
    return {"bids": bids, "asks": asks}


class _SeenEvent:
    __slots__ = ("symbol", "sequence", "content_digest", "result")

    def __init__(
        self,
        symbol: str,
        sequence: int,
        content_digest: str,
        result: dict[str, Any],
    ) -> None:
        self.symbol = symbol
        self.sequence = sequence
        self.content_digest = content_digest
        self.result = result


class EventReplayer:
    """Replays ordered order events for any number of instruments.

    Each symbol owns an independent baseline :class:`Engine`, its own sequence
    cursor and book state; event ids are tracked across the whole replay.
    """

    def __init__(self) -> None:
        self._engines: dict[str, Engine] = {}
        self._last_sequence: dict[str, int] = {}
        self._seen: dict[str, _SeenEvent] = {}

    # -- public use ---------------------------------------------------------

    def submit(self, event: Any) -> dict[str, Any]:
        """Submit a single envelope and return its result dictionary.

        Processing is per-event: accepted earlier events stay committed no
        matter what later events do.
        """
        return self._submit(event)

    def replay(self, events: Any) -> dict[str, Any]:
        """Submit an iterable of envelopes in input order.

        Returns ``{"results", "final_books", "trades", "snapshot"}`` with one
        result per event, the final per-symbol books, every trade produced in
        processing order and a snapshot of the resulting state.
        """
        if not isinstance(events, (list, tuple)):
            raise CanonicalError("events must be a list of event objects")
        results = [self._submit(event) for event in events]
        return {
            "results": results,
            "final_books": self.final_books(),
            "trades": self.all_trades(),
            "snapshot": self.export_snapshot(),
        }

    def final_books(self) -> dict[str, dict[str, list[dict[str, int]]]]:
        """Current public books of every symbol, keyed in sorted symbol order."""
        return {
            symbol: _public_book(self._engines[symbol])
            for symbol in sorted(self._engines)
        }

    def all_trades(self) -> list[dict[str, Any]]:
        """All trades of every symbol, in the order they were produced."""
        trades: list[dict[str, Any]] = []
        for symbol in sorted(self._engines):
            for trade in self._engines[symbol].dump_state()["trade_log"]:
                trades.append(
                    {
                        "symbol": symbol,
                        "sequence": self._trade_sequence(symbol, trade["event_id"]),
                        **trade,
                    }
                )
        return trades

    def _trade_sequence(self, symbol: str, event_id: str) -> int | None:
        seen = self._seen.get(event_id)
        if seen is not None and seen.symbol == symbol:
            return seen.sequence
        return None

    # -- envelope processing ------------------------------------------------

    def _invalid(
        self,
        event_id: Any,
        symbol: Any,
        sequence: Any,
        event_type: Any,
        engine: Engine | None,
    ) -> dict[str, Any]:
        book = _public_book(engine) if engine is not None else {"bids": [], "asks": []}
        return {
            "status": REJECTED,
            "code": INVALID_EVENT,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": event_type,
            "result": None,
            "reason": None,
            "self_trade_prevention": None,
            "trades": [],
            "book_changes": {"before": book, "after": book},
        }

    def _sequence_failure(
        self,
        code: str,
        event_id: str,
        symbol: str,
        sequence: int,
        event_type: str,
        engine: Engine,
    ) -> dict[str, Any]:
        book = _public_book(engine)
        return {
            "status": REJECTED,
            "code": code,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": event_type,
            "result": None,
            "reason": None,
            "self_trade_prevention": None,
            "trades": [],
            "book_changes": {"before": book, "after": book},
        }

    def _submit(self, event: Any) -> dict[str, Any]:
        # --- envelope validation: nothing here mutates replay state --------
        event_id_out: Any = None
        symbol_out: Any = None
        sequence_out: Any = None
        type_out: Any = None
        if not isinstance(event, dict):
            return self._invalid(None, None, None, None, None)
        event_id_out = event.get("event_id")
        symbol_out = event.get("symbol")
        sequence_out = event.get("sequence")
        type_out = event.get("type")
        if not isinstance(event_id_out, str) or event_id_out == "":
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if not isinstance(symbol_out, str) or symbol_out == "":
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if not _is_int(sequence_out) or sequence_out <= 0:
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if not isinstance(type_out, str) or type_out == "":
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if set(event) != _ENVELOPE_KEYS:
            return self._invalid(
                event_id_out, symbol_out, sequence_out, type_out,
                self._engines.get(symbol_out),
            )
        order_event = event.get("event")
        if not isinstance(order_event, dict):
            return self._invalid(
                event_id_out, symbol_out, sequence_out, type_out,
                self._engines.get(symbol_out),
            )
        # The normalized content covers the whole envelope, so any difference
        # (including a changed nested order event or reordered keys) is caught.
        try:
            canonical = canonical_dumps(event)
        except CanonicalError:
            return self._invalid(
                event_id_out, symbol_out, sequence_out, type_out,
                self._engines.get(symbol_out),
            )

        event_id: str = event_id_out
        symbol: str = symbol_out
        sequence: int = sequence_out
        engine = self._engines.get(symbol)

        # --- idempotency: seen ids never reach an engine again -------------
        seen = self._seen.get(event_id)
        if seen is not None:
            same = _digest(canonical) == seen.content_digest
            if same:
                result = dict(seen.result)
                result["status"] = DUPLICATE
                result["code"] = None
                return result
            return {
                "status": REJECTED,
                "code": EVENT_ID_CONFLICT,
                "event_id": event_id,
                "symbol": symbol,
                "sequence": sequence,
                "type": type_out,
                "result": None,
                "reason": None,
                "self_trade_prevention": None,
                "trades": [],
                "book_changes": {
                    "before": _public_book(engine) if engine is not None
                    else {"bids": [], "asks": []},
                    "after": _public_book(engine) if engine is not None
                    else {"bids": [], "asks": []},
                },
            }

        # --- per-symbol sequence ordering ----------------------------------
        if engine is None:
            if sequence != 1:
                fresh_book = {"bids": [], "asks": []}
                return {
                    "status": REJECTED,
                    "code": SEQUENCE_GAP,
                    "event_id": event_id,
                    "symbol": symbol,
                    "sequence": sequence,
                    "type": type_out,
                    "result": None,
                    "reason": None,
                    "self_trade_prevention": None,
                    "trades": [],
                    "book_changes": {"before": fresh_book, "after": fresh_book},
                }
            engine = Engine()
            self._engines[symbol] = engine
            expected = 1
        else:
            expected = self._last_sequence[symbol] + 1
            if sequence < expected:
                return self._sequence_failure(
                    OUT_OF_ORDER, event_id, symbol, sequence, type_out, engine
                )
            if sequence > expected:
                return self._sequence_failure(
                    SEQUENCE_GAP, event_id, symbol, sequence, type_out, engine
                )

        before = _public_book(engine)

        # --- baseline dispatch ---------------------------------------------
        handled = engine.handle_object_position(order_event)
        _eid, base_result, reason, trades, stp, _analysis, _position = handled

        if base_result == "REJECTED" and reason in ("INVALID_SCHEMA", "INVALID_JSON"):
            # Structural order-event errors mirror the baseline: they consume
            # neither the event id nor the symbol's sequence slot, so the same
            # sequence may be corrected and resubmitted.
            after = _public_book(engine)
            return {
                "status": REJECTED,
                "code": INVALID_EVENT,
                "event_id": event_id,
                "symbol": symbol,
                "sequence": sequence,
                "type": type_out,
                "result": None,
                "reason": None,
                "self_trade_prevention": None,
                "trades": [],
                "book_changes": {"before": before, "after": after},
            }

        # A well-formed event occupies its sequence and event id whether the
        # baseline accepted it or refused it for business reasons.
        self._last_sequence[symbol] = sequence
        after = _public_book(engine)
        result: dict[str, Any] = {
            "status": ACCEPTED if base_result != "REJECTED" else REJECTED,
            "code": None,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": type_out,
            "result": base_result,
            "reason": reason,
            "self_trade_prevention": stp,
            "trades": [dict(trade) for trade in trades],
            "book_changes": {"before": before, "after": after},
        }
        self._seen[event_id] = _SeenEvent(
            symbol, sequence, _digest(canonical), result
        )
        return result

    # -- snapshots ----------------------------------------------------------

    def export_snapshot(self) -> dict[str, Any]:
        """Export a complete, checksummed snapshot of the current state.

        May be called after any successful event.  The result is an
        in-memory, JSON-compatible object; this method never writes files.
        """
        config = _canonical_config()
        config_digest = _digest(canonical_dumps(config))
        instruments: dict[str, Any] = {}
        for symbol in sorted(self._engines):
            instruments[symbol] = {
                "last_sequence": self._last_sequence[symbol],
                "engine": self._engines[symbol].dump_state(),
            }
        events = [
            {
                "event_id": event_id,
                "symbol": seen.symbol,
                "sequence": seen.sequence,
                "content_digest": seen.content_digest,
                "result": seen.result,
            }
            for event_id, seen in sorted(
                self._seen.items(),
                key=lambda item: (item[1].symbol, item[1].sequence, item[0]),
            )
        ]
        state: dict[str, Any] = {
            "config_digest": config_digest,
            "instruments": instruments,
            "events": events,
        }
        return {
            "format_version": FORMAT_VERSION,
            "config": config,
            "config_digest": config_digest,
            "state": state,
            "state_digest": _digest(canonical_dumps(state)),
        }

    @classmethod
    def from_snapshot(cls, snapshot: Any) -> EventReplayer:
        """Validate and restore :meth:`export_snapshot` output.

        Version, configuration and the state SHA-256 digest are checked before
        any state is adopted; on failure :class:`SnapshotError` carries the
        precise code and no partial state is created.
        """
        if not isinstance(snapshot, dict):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        version = snapshot.get("format_version")
        if version != FORMAT_VERSION:
            raise SnapshotError(SNAPSHOT_VERSION_UNSUPPORTED)

        config = snapshot.get("config")
        expected_config = _canonical_config()
        config_digest = snapshot.get("config_digest")
        expected_config_digest = _digest(canonical_dumps(expected_config))
        if (
            not isinstance(config, dict)
            or canonical_dumps(config) != canonical_dumps(expected_config)
            or config_digest != expected_config_digest
        ):
            raise SnapshotError(CONFIG_MISMATCH)

        state = snapshot.get("state")
        state_digest = snapshot.get("state_digest")
        if (
            not isinstance(state, dict)
            or not isinstance(state_digest, str)
            or _digest(canonical_dumps(state)) != state_digest
        ):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        try:
            replayer = cls._build_state(state, expected_config_digest)
        except (KeyError, TypeError, ValueError, CanonicalError):
            raise SnapshotError(SNAPSHOT_CORRUPT)
        return replayer

    @classmethod
    def _build_state(cls, state: dict[str, Any], config_digest: str) -> EventReplayer:
        if state.get("config_digest") != config_digest:
            raise SnapshotError(CONFIG_MISMATCH)
        instruments = state["instruments"]
        entries = state["events"]
        if not isinstance(instruments, dict) or not isinstance(entries, list):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        replayer = cls()
        engines: dict[str, Engine] = {}
        last_sequence: dict[str, int] = {}
        for symbol, instrument in instruments.items():
            if not isinstance(symbol, str) or not isinstance(instrument, dict):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            last = instrument["last_sequence"]
            if not _is_int(last) or last < 0:
                raise SnapshotError(SNAPSHOT_CORRUPT)
            engines[symbol] = Engine.from_state(instrument["engine"])
            last_sequence[symbol] = last
        replayer._engines = engines
        replayer._last_sequence = last_sequence

        seen: dict[str, _SeenEvent] = {}
        for entry in entries:
            if not isinstance(entry, dict):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            event_id = entry["event_id"]
            symbol = entry["symbol"]
            sequence = entry["sequence"]
            content_digest = entry["content_digest"]
            stored_result = entry["result"]
            if (
                not isinstance(event_id, str)
                or not isinstance(symbol, str)
                or not _is_int(sequence)
                or not isinstance(content_digest, str)
                or not isinstance(stored_result, dict)
                or symbol not in engines
                or event_id in seen
            ):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            seen[event_id] = _SeenEvent(
                symbol, sequence, content_digest, stored_result
            )
        replayer._seen = seen
        return replayer


def _canonical_config() -> dict[str, Any]:
    return json.loads(json.dumps(_CONFIG, ensure_ascii=False))


# --- Module-level convenience entry points ----------------------------------


def replay_events(events: Any, *, snapshot: Any = None) -> dict[str, Any]:
    """Replay one ordered batch of envelopes in a single public call.

    With *snapshot* omitted the replay starts from an empty state; otherwise the
    snapshot is validated and restored first (raising :class:`SnapshotError`).
    Different symbols keep independent sequences and books, while input order
    within and across symbols is preserved exactly.
    """
    replayer = EventReplayer() if snapshot is None else EventReplayer.from_snapshot(snapshot)
    return replayer.replay(events)


def restore_snapshot(snapshot: Any) -> EventReplayer:
    """Validate and restore a snapshot, returning a ready :class:`EventReplayer`."""
    return EventReplayer.from_snapshot(snapshot)

toolUseResult.content:
"""Deterministic multi-instrument event replay with resumable snapshots.

This layer adds nothing to the baseline matching semantics: each financial
event (``ADD`` / ``CANCEL`` / ``REPLACE`` and the baseline query events) is
handled by an independent per-symbol :class:`~order_book_engine.engine.Engine`
exactly as the baseline does.  It additionally provides:

* strict per-symbol ``sequence`` streams (gaps and regressions rejected);
* idempotent replay keyed by ``event_id`` over normalized event content;
* per-event results carrying trades and explicit before/after book changes;
* canonical, byte-comparable JSON serialization;
* self-describing, checksummed in-memory snapshots that resume a replay so
  trade ids, trade order and final results are identical to an uninterrupted
  run.

No file is ever read or written here: events, results and snapshots are plain
JSON-compatible Python objects handed to or returned by the public entry
points.  Persistence, if desired, is the caller's responsibility.
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

from .engine import Engine

# --- Replay outcome statuses ------------------------------------------------

ACCEPTED = "ACCEPTED"
"""The event was well formed, in sequence and produced a baseline result."""

REJECTED = "REJECTED"
"""The event was invalid, out of sequence or refused by baseline rules."""

DUPLICATE = "DUPLICATE"
"""A seen ``event_id`` was replayed with byte-identical normalized content."""

# --- Replay rejection codes -------------------------------------------------

INVALID_EVENT = "INVALID_EVENT"
"""Missing fields, illegal values, an unknown envelope/order event type."""

SEQUENCE_GAP = "SEQUENCE_GAP"
"""The symbol's sequence jumped over one or more expected values."""

OUT_OF_ORDER = "OUT_OF_ORDER"
"""The symbol's sequence did not strictly increase."""

EVENT_ID_CONFLICT = "EVENT_ID_CONFLICT"
"""A seen ``event_id`` arrived with different normalized content."""

# --- Snapshot rejection codes ----------------------------------------------

SNAPSHOT_CORRUPT = "SNAPSHOT_CORRUPT"
SNAPSHOT_VERSION_UNSUPPORTED = "SNAPSHOT_VERSION_UNSUPPORTED"
CONFIG_MISMATCH = "CONFIG_MISMATCH"

FORMAT_VERSION = "order-book-replay/1"

# Baseline behaviour fixed by the snapshot configuration summary.  Values are
# sorted so the summary itself is canonical.
_CONFIG: dict[str, object] = {
    "matching": "price-time-priority",
    "engine_state_format": 1,
    "trade_id_start": 1,
    "supported_order_types": ["ICEBERG", "LIMIT", "MARKET"],
    "supported_sides": ["BUY", "SELL"],
    "supported_time_in_force": ["FOK", "GTC", "IOC"],
    "order_event_types": ["ADD", "CANCEL", "REPLACE"],
}

_ENVELOPE_KEYS = frozenset({"event_id", "symbol", "sequence", "type", "event"})


class CanonicalError(ValueError):
    """Raised when an object cannot be represented in canonical JSON."""


class SnapshotError(ValueError):
    """Raised when a snapshot cannot be restored.

    ``code`` is one of :data:`SNAPSHOT_CORRUPT`,
    :data:`SNAPSHOT_VERSION_UNSUPPORTED` or :data:`CONFIG_MISMATCH`.  A failed
    restoration never creates a partially restored replayer.
    """

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


class _Ordered:
    """Total, type-stable ordering wrapper for canonical JSON key sorting."""

    __slots__ = ("value",)

    def __init__(self, value: Any) -> None:
        self.value = value

    def _rank(self) -> tuple[int, Any]:
        value = self.value
        if value is None:
            return (0, 0)
        if isinstance(value, bool):
            return (1, int(value))
        if isinstance(value, (int, float)):
            return (2, value)
        if isinstance(value, str):
            return (3, value)
        if isinstance(value, list):
            return (4, None)
        if isinstance(value, dict):
            return (5, None)
        return (6, repr(value))

    def __lt__(self, other: _Ordered) -> bool:
        rank = self._rank()
        other_rank = other._rank()
        if rank[0] != other_rank[0]:
            return rank[0] < other_rank[0]
        if rank[0] in (4, 5):
            # Containers of different shapes never compare equal; fall back to
            # a stable textual tiebreaker instead of recursing into unordered
            # containers.
            return canonical_dumps(self.value) < canonical_dumps(other.value)
        return rank[1] < other_rank[1]

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, _Ordered):
            return NotImplemented
        return canonical_dumps(self.value) == canonical_dumps(other.value)

    def __hash__(self) -> int:
        return hash(canonical_dumps(self.value))


def canonical_dumps(obj: Any) -> bytes:
    """Serialize *obj* to deterministic, byte-comparable canonical JSON.

    Object keys are sorted by a type-stable total order, compact separators
    are used and non-ASCII characters pass through unescaped, exactly as in the
    baseline replay output.  Identical content always yields identical bytes
    regardless of insertion order.
    """
    return json.dumps(
        _canonicalize(obj),
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")


def _canonicalize(obj: Any) -> Any:
    if obj is None or isinstance(obj, (str, bool, int, float)):
        return obj
    if isinstance(obj, dict):
        return [
            [_canonicalize(_Ordered(key).value), _canonicalize(value)]
            for key, value in sorted(
                ((_Ordered(k), v) for k, v in obj.items()),
                key=lambda item: item[0],
            )
        ]
    if isinstance(obj, (list, tuple)):
        return [_canonicalize(item) for item in obj]
    raise CanonicalError(f"object is not JSON-compatible: {type(obj)!r}")


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _is_int(value: Any) -> bool:
    # ``bool`` is a subclass of ``int`` and is not a sequence number.
    return isinstance(value, int) and not isinstance(value, bool)


def _public_book(engine: Engine) -> dict[str, list[dict[str, int]]]:
    bids, asks = engine.snapshot()
    return {"bids": bids, "asks": asks}


class _SeenEvent:
    __slots__ = ("symbol", "sequence", "content_digest", "result")

    def __init__(
        self,
        symbol: str,
        sequence: int,
        content_digest: str,
        result: dict[str, Any],
    ) -> None:
        self.symbol = symbol
        self.sequence = sequence
        self.content_digest = content_digest
        self.result = result


class EventReplayer:
    """Replays ordered order events for any number of instruments.

    Each symbol owns an independent baseline :class:`Engine`, its own sequence
    cursor and book state; event ids are tracked across the whole replay.
    """

    def __init__(self) -> None:
        self._engines: dict[str, Engine] = {}
        self._last_sequence: dict[str, int] = {}
        self._seen: dict[str, _SeenEvent] = {}

    # -- public use ---------------------------------------------------------

    def submit(self, event: Any) -> dict[str, Any]:
        """Submit a single envelope and return its result dictionary.

        Processing is per-event: accepted earlier events stay committed no
        matter what later events do.
        """
        return self._submit(event)

    def replay(self, events: Any) -> dict[str, Any]:
        """Submit an iterable of envelopes in input order.

        Returns ``{"results", "final_books", "trades", "snapshot"}`` with one
        result per event, the final per-symbol books, every trade produced in
        processing order and a snapshot of the resulting state.
        """
        if not isinstance(events, (list, tuple)):
            raise CanonicalError("events must be a list of event objects")
        results = [self._submit(event) for event in events]
        return {
            "results": results,
            "final_books": self.final_books(),
            "trades": self.all_trades(),
            "snapshot": self.export_snapshot(),
        }

    def final_books(self) -> dict[str, dict[str, list[dict[str, int]]]]:
        """Current public books of every symbol, keyed in sorted symbol order."""
        return {
            symbol: _public_book(self._engines[symbol])
            for symbol in sorted(self._engines)
        }

    def all_trades(self) -> list[dict[str, Any]]:
        """All trades of every symbol, in the order they were produced."""
        trades: list[dict[str, Any]] = []
        for symbol in sorted(self._engines):
            for trade in self._engines[symbol].dump_state()["trade_log"]:
                trades.append(
                    {
                        "symbol": symbol,
                        "sequence": self._trade_sequence(symbol, trade["event_id"]),
                        **trade,
                    }
                )
        return trades

    def _trade_sequence(self, symbol: str, event_id: str) -> int | None:
        seen = self._seen.get(event_id)
        if seen is not None and seen.symbol == symbol:
            return seen.sequence
        return None

    # -- envelope processing ------------------------------------------------

    def _invalid(
        self,
        event_id: Any,
        symbol: Any,
        sequence: Any,
        event_type: Any,
        engine: Engine | None,
    ) -> dict[str, Any]:
        book = _public_book(engine) if engine is not None else {"bids": [], "asks": []}
        return {
            "status": REJECTED,
            "code": INVALID_EVENT,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": event_type,
            "result": None,
            "reason": None,
            "self_trade_prevention": None,
            "trades": [],
            "book_changes": {"before": book, "after": book},
        }

    def _sequence_failure(
        self,
        code: str,
        event_id: str,
        symbol: str,
        sequence: int,
        event_type: str,
        engine: Engine,
    ) -> dict[str, Any]:
        book = _public_book(engine)
        return {
            "status": REJECTED,
            "code": code,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": event_type,
            "result": None,
            "reason": None,
            "self_trade_prevention": None,
            "trades": [],
            "book_changes": {"before": book, "after": book},
        }

    def _submit(self, event: Any) -> dict[str, Any]:
        # --- envelope validation: nothing here mutates replay state --------
        event_id_out: Any = None
        symbol_out: Any = None
        sequence_out: Any = None
        type_out: Any = None
        if not isinstance(event, dict):
            return self._invalid(None, None, None, None, None)
        event_id_out = event.get("event_id")
        symbol_out = event.get("symbol")
        sequence_out = event.get("sequence")
        type_out = event.get("type")
        if not isinstance(event_id_out, str) or event_id_out == "":
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if not isinstance(symbol_out, str) or symbol_out == "":
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if not _is_int(sequence_out) or sequence_out <= 0:
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if not isinstance(type_out, str) or type_out == "":
            return self._invalid(event_id_out, symbol_out, sequence_out, type_out, None)
        if set(event) != _ENVELOPE_KEYS:
            return self._invalid(
                event_id_out, symbol_out, sequence_out, type_out,
                self._engines.get(symbol_out),
            )
        order_event = event.get("event")
        if not isinstance(order_event, dict):
            return self._invalid(
                event_id_out, symbol_out, sequence_out, type_out,
                self._engines.get(symbol_out),
            )
        # The normalized content covers the whole envelope, so any difference
        # (including a changed nested order event or reordered keys) is caught.
        try:
            canonical = canonical_dumps(event)
        except CanonicalError:
            return self._invalid(
                event_id_out, symbol_out, sequence_out, type_out,
                self._engines.get(symbol_out),
            )

        event_id: str = event_id_out
        symbol: str = symbol_out
        sequence: int = sequence_out
        engine = self._engines.get(symbol)

        # --- idempotency: seen ids never reach an engine again -------------
        seen = self._seen.get(event_id)
        if seen is not None:
            same = _digest(canonical) == seen.content_digest
            if same:
                result = dict(seen.result)
                result["status"] = DUPLICATE
                result["code"] = None
                return result
            return {
                "status": REJECTED,
                "code": EVENT_ID_CONFLICT,
                "event_id": event_id,
                "symbol": symbol,
                "sequence": sequence,
                "type": type_out,
                "result": None,
                "reason": None,
                "self_trade_prevention": None,
                "trades": [],
                "book_changes": {
                    "before": _public_book(engine) if engine is not None
                    else {"bids": [], "asks": []},
                    "after": _public_book(engine) if engine is not None
                    else {"bids": [], "asks": []},
                },
            }

        # --- per-symbol sequence ordering ----------------------------------
        if engine is None:
            if sequence != 1:
                fresh_book = {"bids": [], "asks": []}
                return {
                    "status": REJECTED,
                    "code": SEQUENCE_GAP,
                    "event_id": event_id,
                    "symbol": symbol,
                    "sequence": sequence,
                    "type": type_out,
                    "result": None,
                    "reason": None,
                    "self_trade_prevention": None,
                    "trades": [],
                    "book_changes": {"before": fresh_book, "after": fresh_book},
                }
            engine = Engine()
            self._engines[symbol] = engine
            expected = 1
        else:
            expected = self._last_sequence[symbol] + 1
            if sequence < expected:
                return self._sequence_failure(
                    OUT_OF_ORDER, event_id, symbol, sequence, type_out, engine
                )
            if sequence > expected:
                return self._sequence_failure(
                    SEQUENCE_GAP, event_id, symbol, sequence, type_out, engine
                )

        before = _public_book(engine)

        # --- baseline dispatch ---------------------------------------------
        handled = engine.handle_object_position(order_event)
        _eid, base_result, reason, trades, stp, _analysis, _position = handled

        if base_result == "REJECTED" and reason in ("INVALID_SCHEMA", "INVALID_JSON"):
            # Structural order-event errors mirror the baseline: they consume
            # neither the event id nor the symbol's sequence slot, so the same
            # sequence may be corrected and resubmitted.
            after = _public_book(engine)
            return {
                "status": REJECTED,
                "code": INVALID_EVENT,
                "event_id": event_id,
                "symbol": symbol,
                "sequence": sequence,
                "type": type_out,
                "result": None,
                "reason": None,
                "self_trade_prevention": None,
                "trades": [],
                "book_changes": {"before": before, "after": after},
            }

        # A well-formed event occupies its sequence and event id whether the
        # baseline accepted it or refused it for business reasons.
        self._last_sequence[symbol] = sequence
        after = _public_book(engine)
        result: dict[str, Any] = {
            "status": ACCEPTED if base_result != "REJECTED" else REJECTED,
            "code": None,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": type_out,
            "result": base_result,
            "reason": reason,
            "self_trade_prevention": stp,
            "trades": [dict(trade) for trade in trades],
            "book_changes": {"before": before, "after": after},
        }
        self._seen[event_id] = _SeenEvent(
            symbol, sequence, _digest(canonical), result
        )
        return result

    # -- snapshots ----------------------------------------------------------

    def export_snapshot(self) -> dict[str, Any]:
        """Export a complete, checksummed snapshot of the current state.

        May be called after any successful event.  The result is an
        in-memory, JSON-compatible object; this method never writes files.
        """
        config = _canonical_config()
        config_digest = _digest(canonical_dumps(config))
        instruments: dict[str, Any] = {}
        for symbol in sorted(self._engines):
            instruments[symbol] = {
                "last_sequence": self._last_sequence[symbol],
                "engine": self._engines[symbol].dump_state(),
            }
        events = [
            {
                "event_id": event_id,
                "symbol": seen.symbol,
                "sequence": seen.sequence,
                "content_digest": seen.content_digest,
                "result": seen.result,
            }
            for event_id, seen in sorted(
                self._seen.items(),
                key=lambda item: (item[1].symbol, item[1].sequence, item[0]),
            )
        ]
        state: dict[str, Any] = {
            "config_digest": config_digest,
            "instruments": instruments,
            "events": events,
        }
        return {
            "format_version": FORMAT_VERSION,
            "config": config,
            "config_digest": config_digest,
            "state": state,
            "state_digest": _digest(canonical_dumps(state)),
        }

    @classmethod
    def from_snapshot(cls, snapshot: Any) -> EventReplayer:
        """Validate and restore :meth:`export_snapshot` output.

        Version, configuration and the state SHA-256 digest are checked before
        any state is adopted; on failure :class:`SnapshotError` carries the
        precise code and no partial state is created.
        """
        if not isinstance(snapshot, dict):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        version = snapshot.get("format_version")
        if version != FORMAT_VERSION:
            raise SnapshotError(SNAPSHOT_VERSION_UNSUPPORTED)

        config = snapshot.get("config")
        expected_config = _canonical_config()
        config_digest = snapshot.get("config_digest")
        expected_config_digest = _digest(canonical_dumps(expected_config))
        if (
            not isinstance(config, dict)
            or canonical_dumps(config) != canonical_dumps(expected_config)
            or config_digest != expected_config_digest
        ):
            raise SnapshotError(CONFIG_MISMATCH)

        state = snapshot.get("state")
        state_digest = snapshot.get("state_digest")
        if (
            not isinstance(state, dict)
            or not isinstance(state_digest, str)
            or _digest(canonical_dumps(state)) != state_digest
        ):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        try:
            replayer = cls._build_state(state, expected_config_digest)
        except (KeyError, TypeError, ValueError, CanonicalError):
            raise SnapshotError(SNAPSHOT_CORRUPT)
        return replayer

    @classmethod
    def _build_state(cls, state: dict[str, Any], config_digest: str) -> EventReplayer:
        if state.get("config_digest") != config_digest:
            raise SnapshotError(CONFIG_MISMATCH)
        instruments = state["instruments"]
        entries = state["events"]
        if not isinstance(instruments, dict) or not isinstance(entries, list):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        replayer = cls()
        engines: dict[str, Engine] = {}
        last_sequence: dict[str, int] = {}
        for symbol, instrument in instruments.items():
            if not isinstance(symbol, str) or not isinstance(instrument, dict):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            last = instrument["last_sequence"]
            if not _is_int(last) or last < 0:
                raise SnapshotError(SNAPSHOT_CORRUPT)
            engines[symbol] = Engine.from_state(instrument["engine"])
            last_sequence[symbol] = last
        replayer._engines = engines
        replayer._last_sequence = last_sequence

        seen: dict[str, _SeenEvent] = {}
        for entry in entries:
            if not isinstance(entry, dict):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            event_id = entry["event_id"]
            symbol = entry["symbol"]
            sequence = entry["sequence"]
            content_digest = entry["content_digest"]
            stored_result = entry["result"]
            if (
                not isinstance(event_id, str)
                or not isinstance(symbol, str)
                or not _is_int(sequence)
                or not isinstance(content_digest, str)
                or not isinstance(stored_result, dict)
                or symbol not in engines
                or event_id in seen
            ):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            seen[event_id] = _SeenEvent(
                symbol, sequence, content_digest, stored_result
            )
        replayer._seen = seen
        return replayer


def _canonical_config() -> dict[str, Any]:
    return json.loads(json.dumps(_CONFIG, ensure_ascii=False))


# --- Module-level convenience entry points ----------------------------------


def replay_events(events: Any, *, snapshot: Any = None) -> dict[str, Any]:
    """Replay one ordered batch of envelopes in a single public call.

    With *snapshot* omitted the replay starts from an empty state; otherwise the
    snapshot is validated and restored first (raising :class:`SnapshotError`).
    Different symbols keep independent sequences and books, while input order
    within and across symbols is preserved exactly.
    """
    replayer = EventReplayer() if snapshot is None else EventReplayer.from_snapshot(snapshot)
    return replayer.replay(events)


def restore_snapshot(snapshot: Any) -> EventReplayer:
    """Validate and restore a snapshot, returning a ready :class:`EventReplayer`."""
    return EventReplayer.from_snapshot(snapshot)

input.content:
"""Deterministic multi-instrument event replay with resumable snapshots.

This layer adds nothing to the baseline matching semantics: each financial
event (``ADD`` / ``CANCEL`` / ``REPLACE`` and the baseline query events) is
handled by an independent per-symbol :class:`~order_book_engine.engine.Engine`
exactly as the baseline does.  It additionally provides:

* strict per-symbol ``sequence`` streams (gaps and regressions rejected);
* idempotent replay keyed by ``event_id`` over normalized event content;
* per-event results carrying trades and explicit before/after book changes;
* canonical, byte-comparable JSON serialization;
* self-describing, checksummed in-memory snapshots that resume a replay so
  trade ids, trade order and final results are identical to an uninterrupted
  run.

No file is ever read or written here: events, results and snapshots are plain
JSON-compatible Python objects handed to or returned by the public entry
points.  Persistence, if desired, is the caller's responsibility.
"""

from __future__ import annotations

import copy
import hashlib
import json
import math
from typing import Any

from .engine import Engine

# --- Replay outcome statuses ------------------------------------------------

ACCEPTED = "ACCEPTED"
"""The event was well formed, in sequence and produced a baseline result."""

REJECTED = "REJECTED"
"""The event was invalid, out of sequence or refused by baseline rules."""

DUPLICATE = "DUPLICATE"
"""A seen ``event_id`` was replayed with byte-identical normalized content."""

# --- Replay rejection codes -------------------------------------------------

INVALID_EVENT = "INVALID_EVENT"
"""Missing fields, illegal values, or an unknown event type."""

SEQUENCE_GAP = "SEQUENCE_GAP"
"""The symbol's sequence jumped over one or more expected values."""

OUT_OF_ORDER = "OUT_OF_ORDER"
"""The symbol's sequence did not strictly increase."""

EVENT_ID_CONFLICT = "EVENT_ID_CONFLICT"
"""A seen ``event_id`` arrived with different normalized content."""

# --- Snapshot rejection codes ----------------------------------------------

SNAPSHOT_CORRUPT = "SNAPSHOT_CORRUPT"
SNAPSHOT_VERSION_UNSUPPORTED = "SNAPSHOT_VERSION_UNSUPPORTED"
CONFIG_MISMATCH = "CONFIG_MISMATCH"

FORMAT_VERSION = "order-book-replay/1"

# Baseline behaviour summarized inside every snapshot.  The contents pin the
# matching semantics a resume expects; lists are kept sorted so the summary
# serializes canonically.
_CONFIG: dict[str, Any] = {
    "matching": "price-time-priority",
    "engine_state_format": 1,
    "trade_id_start": 1,
    "supported_order_types": ["ICEBERG", "LIMIT", "MARKET"],
    "supported_sides": ["BUY", "SELL"],
    "supported_time_in_force": ["FOK", "GTC", "IOC"],
    "order_event_types": ["ADD", "CANCEL", "REPLACE"],
}

_ENVELOPE_KEYS = frozenset({"event_id", "symbol", "sequence", "type", "event"})


class CanonicalError(ValueError):
    """Raised when an object cannot be represented in canonical JSON."""


class SnapshotError(ValueError):
    """Raised when a snapshot cannot be restored.

    ``code`` is one of :data:`SNAPSHOT_CORRUPT`,
    :data:`SNAPSHOT_VERSION_UNSUPPORTED` or :data:`CONFIG_MISMATCH`.  A failed
    restoration never creates a partially restored replayer.
    """

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


class _Ordered:
    """Total, type-stable ordering wrapper for canonical JSON key sorting."""

    __slots__ = ("value")

    def __init__(self, value: Any) -> None:
        self.value = value

    def _rank(self) -> tuple[int, Any]:
        value = self.value
        if value is None:
            return (0, 0)
        if isinstance(value, bool):
            return (1, int(value))
        if isinstance(value, int):
            return (2, value)
        if isinstance(value, float):
            return (3, value)
        if isinstance(value, str):
            return (4, value)
        if isinstance(value, list):
            return (5, None)
        if isinstance(value, dict):
            return (6, None)
        return (7, repr(value))

    def __lt__(self, other: _Ordered) -> bool:
        rank = self._rank()
        other_rank = other._rank()
        if rank[0] != other_rank[0]:
            return rank[0] < other_rank[0]
        if rank[0] in (5, 6):
            # Containers of the same shape never compare directly; fall back to
            # their own canonical bytes instead of recursing unordered.
            return canonical_dumps(self.value) < canonical_dumps(other.value)
        return rank[1] < other_rank[1]


def canonical_dumps(obj: Any) -> bytes:
    """Serialize *obj* to deterministic, byte-comparable canonical JSON.

    Object keys are sorted by a type-stable total order, compact separators
    are used and non-ASCII characters pass through unescaped, matching the
    baseline replay output.  Identical content always yields identical bytes
    regardless of insertion order.
    """
    return json.dumps(
        _canonicalize(obj),
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")


def _canonicalize(obj: Any) -> Any:
    if obj is None or isinstance(obj, (str, bool, int)):
        return obj
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise CanonicalError("non-finite floats are not canonicalizable")
        return obj
    if isinstance(obj, dict):
        return [
            [_canonicalize(key), _canonicalize(value)]
            for key, value in sorted(
                ((_Ordered(k), v) for k, v in obj.items()),
                key=lambda item: item[0],
            )
        ]
    if isinstance(obj, (list, tuple)):
        return [_canonicalize(item) for item in obj]
    raise CanonicalError(f"object is not JSON-compatible: {type(obj)!r}")


def _digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _is_int(value: Any) -> bool:
    # ``bool`` is a subclass of ``int`` and is not a sequence number.
    return isinstance(value, int) and not isinstance(value, bool)


def _is_non_empty_str(value: Any) -> bool:
    return isinstance(value, str) and value != ""


def _public_book(engine: Engine) -> dict[str, list[dict[str, int]]]:
    bids, asks = engine.snapshot()
    return {"bids": bids, "asks": asks}


_EMPTY_BOOK: dict[str, list[dict[str, int]]] = {"bids": [], "asks": []}


class _SeenEvent:
    __slots__ = ("symbol", "sequence", "content_digest", "result")

    def __init__(
        self,
        symbol: str,
        sequence: int,
        content_digest: str,
        result: dict[str, Any],
    ) -> None:
        self.symbol = symbol
        self.sequence = sequence
        self.content_digest = content_digest
        self.result = result


class EventReplayer:
    """Replays ordered order events for any number of instruments.

    Each symbol owns an independent baseline :class:`Engine`, its own sequence
    cursor and book state; event ids and the cross-symbol submission order are
    tracked for the whole replay.
    """

    def __init__(self) -> None:
        self._engines: dict[str, Engine] = {}
        self._last_sequence: dict[str, int] = {}
        self._seen: dict[str, _SeenEvent] = {}
        # event_ids of well-formed events in cross-symbol submission order.
        self._order: list[str] = []

    # -- public use ---------------------------------------------------------

    def submit(self, event: Any) -> dict[str, Any]:
        """Submit a single envelope and return its result dictionary.

        Processing is per-event: accepted earlier events stay committed no
        matter what later events do.
        """
        return self._submit(event)

    def replay(self, events: Any) -> dict[str, Any]:
        """Submit an ordered list of envelopes in input order.

        Returns ``{"results", "final_books", "trades", "snapshot"}`` with one
        result per event, the final per-symbol books, every trade produced in
        cross-symbol submission order and a snapshot of the resulting state.
        """
        if not isinstance(events, list):
            raise CanonicalError("events must be a list of event objects")
        results = [self._submit(event) for event in events]
        return {
            "results": results,
            "final_books": self.final_books(),
            "trades": self.all_trades(),
            "snapshot": self.export_snapshot(),
        }

    def final_books(self) -> dict[str, dict[str, list[dict[str, int]]]]:
        """Current public books of every symbol, keyed in sorted symbol order."""
        return {
            symbol: _public_book(self._engines[symbol])
            for symbol in sorted(self._engines)
        }

    def all_trades(self) -> list[dict[str, Any]]:
        """All trades of every symbol, in cross-symbol submission order."""
        trades: list[dict[str, Any]] = []
        for event_id in self._order:
            seen = self._seen[event_id]
            for trade in seen.result["trades"]:
                trades.append(
                    {
                        "symbol": seen.symbol,
                        "sequence": seen.sequence,
                        "event_id": event_id,
                        "trade_id": trade["trade_id"],
                        "maker_order_id": trade["maker_order_id"],
                        "taker_order_id": trade["taker_order_id"],
                        "price": trade["price"],
                        "quantity": trade["quantity"],
                    }
                )
        return trades

    # -- envelope processing ------------------------------------------------

    def _rejection(
        self,
        code: str,
        event_id: Any,
        symbol: Any,
        sequence: Any,
        event_type: Any,
        book: dict[str, list[dict[str, int]]],
    ) -> dict[str, Any]:
        return {
            "status": REJECTED,
            "code": code,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": event_type,
            "result": None,
            "reason": None,
            "self_trade_prevention": None,
            "execution_analysis": None,
            "position_analysis": None,
            "trades": [],
            "book_changes": {"before": book, "after": book},
        }

    def _submit(self, event: Any) -> dict[str, Any]:
        # --- envelope validation: nothing here mutates replay state --------
        if not isinstance(event, dict):
            return self._rejection(
                INVALID_EVENT, None, None, None, None, _EMPTY_BOOK
            )
        event_id = event.get("event_id")
        symbol = event.get("symbol")
        sequence = event.get("sequence")
        event_type = event.get("type")
        if not _is_non_empty_str(event_id):
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _EMPTY_BOOK,
            )
        if not _is_non_empty_str(symbol):
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _EMPTY_BOOK,
            )
        if not _is_int(sequence) or sequence <= 0:
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _EMPTY_BOOK,
            )
        if not _is_non_empty_str(event_type):
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _EMPTY_BOOK,
            )
        engine = self._engines.get(symbol)
        if set(event) != _ENVELOPE_KEYS:
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _public_book(engine) if engine is not None else _EMPTY_BOOK,
            )
        order_event = event.get("event")
        if not isinstance(order_event, dict):
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _public_book(engine) if engine is not None else _EMPTY_BOOK,
            )
        # The inner event is a verbatim baseline object; its identifiers must
        # agree with the envelope so the engine sees exactly the stream the
        # caller declared.
        if (
            order_event.get("event_id") != event_id
            or order_event.get("type") != event_type
        ):
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _public_book(engine) if engine is not None else _EMPTY_BOOK,
            )
        # The normalized content covers the whole envelope, so any difference
        # (including a changed nested order event or reordered keys) is caught.
        try:
            canonical = canonical_dumps(event)
        except CanonicalError:
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type,
                _public_book(engine) if engine is not None else _EMPTY_BOOK,
            )

        # --- idempotency: seen ids never reach an engine again -------------
        seen = self._seen.get(event_id)
        if seen is not None:
            if _digest(canonical) == seen.content_digest:
                duplicate = copy.deepcopy(seen.result)
                duplicate["status"] = DUPLICATE
                duplicate["code"] = None
                return duplicate
            return self._rejection(
                EVENT_ID_CONFLICT, event_id, symbol, sequence, event_type,
                _public_book(engine) if engine is not None else _EMPTY_BOOK,
            )

        # --- per-symbol sequence ordering ----------------------------------
        if engine is None:
            if sequence != 1:
                return self._rejection(
                    SEQUENCE_GAP, event_id, symbol, sequence, event_type,
                    _EMPTY_BOOK,
                )
            engine = Engine()
            self._engines[symbol] = engine
            expected = 1
        else:
            expected = self._last_sequence[symbol] + 1
            if sequence < expected:
                return self._rejection(
                    OUT_OF_ORDER, event_id, symbol, sequence, event_type,
                    _public_book(engine),
                )
            if sequence > expected:
                return self._rejection(
                    SEQUENCE_GAP, event_id, symbol, sequence, event_type,
                    _public_book(engine),
                )

        before = _public_book(engine)

        # --- baseline dispatch (matching rules are never redefined) --------
        _eid, base_result, reason, trades, stp, analysis, position = (
            engine.handle_object_position(order_event)
        )

        if base_result == "REJECTED" and reason == "INVALID_SCHEMA":
            # Structural order-event errors mirror the baseline: they consume
            # neither the event id nor the symbol's sequence slot, so the same
            # sequence may be corrected and resubmitted.
            return self._rejection(
                INVALID_EVENT, event_id, symbol, sequence, event_type, before
            )

        # A well-formed event occupies its sequence and event id whether the
        # baseline accepted it or refused it for business reasons; failed
        # events leave no order, trade, counter or book change behind.
        self._last_sequence[symbol] = sequence
        after = _public_book(engine)
        result: dict[str, Any] = {
            "status": ACCEPTED if base_result != "REJECTED" else REJECTED,
            "code": None,
            "event_id": event_id,
            "symbol": symbol,
            "sequence": sequence,
            "type": event_type,
            "result": base_result,
            "reason": reason,
            "self_trade_prevention": copy.deepcopy(stp),
            "execution_analysis": copy.deepcopy(analysis),
            "position_analysis": copy.deepcopy(position),
            "trades": [dict(trade) for trade in trades],
            "book_changes": {"before": before, "after": after},
        }
        self._seen[event_id] = _SeenEvent(
            symbol, sequence, _digest(canonical), result
        )
        self._order.append(event_id)
        return result

    # -- snapshots ----------------------------------------------------------

    def export_snapshot(self) -> dict[str, Any]:
        """Export a complete, checksummed snapshot of the current state.

        May be called after any successfully processed event.  The result is
        an in-memory, JSON-compatible object; this method never writes files.
        The snapshot preserves price-time priority, remaining quantities,
        iceberg visible slices and replenishment state, each symbol's last
        sequence, the cumulative trade journal and the trade id counters.
        """
        config = _canonical_config()
        config_digest = _digest(canonical_dumps(config))
        instruments: dict[str, Any] = {}
        for symbol in sorted(self._engines):
            instruments[symbol] = {
                "last_sequence": self._last_sequence[symbol],
                "engine": self._engines[symbol].dump_state(),
            }
        events = [
            {
                "event_id": event_id,
                "symbol": self._seen[event_id].symbol,
                "sequence": self._seen[event_id].sequence,
                "content_digest": self._seen[event_id].content_digest,
                "result": copy.deepcopy(self._seen[event_id].result),
            }
            for event_id in self._order
        ]
        state: dict[str, Any] = {
            "config_digest": config_digest,
            "instruments": instruments,
            "event_order": list(self._order),
            "events": events,
        }
        return {
            "format_version": format_version(),
            "config": config,
            "config_digest": config_digest,
            "state": state,
            "state_digest": _digest(canonical_dumps(state)),
        }

    @classmethod
    def from_snapshot(cls, snapshot: Any) -> EventReplayer:
        """Validate and restore :meth:`export_snapshot` output.

        Version, configuration and the state SHA-256 digest are checked before
        any state is adopted; on failure :class:`SnapshotError` carries the
        precise code and no partial state is created.  On success the resumed
        replay generates identical trade ids, trade order and final results.
        """
        if not isinstance(snapshot, dict):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        if snapshot.get("format_version") != format_version():
            raise SnapshotError(SNAPSHOT_VERSION_UNSUPPORTED)

        config = snapshot.get("config")
        expected_config = _canonical_config()
        expected_config_digest = _digest(canonical_dumps(expected_config))
        if (
            not isinstance(config, dict)
            or canonical_dumps(config) != canonical_dumps(expected_config)
            or snapshot.get("config_digest") != expected_config_digest
        ):
            raise SnapshotError(CONFIG_MISMATCH)

        state = snapshot.get("state")
        state_digest = snapshot.get("state_digest")
        if (
            not isinstance(state, dict)
            or not isinstance(state_digest, str)
            or _digest(canonical_dumps(state)) != state_digest
        ):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        try:
            return cls._build_state(state, expected_config_digest)
        except SnapshotError:
            raise
        except (KeyError, TypeError, ValueError, CanonicalError) as exc:
            raise SnapshotError(SNAPSHOT_CORRUPT) from exc

    @classmethod
    def _build_state(cls, state: dict[str, Any], config_digest: str) -> EventReplayer:
        if state.get("config_digest") != config_digest:
            raise SnapshotError(CONFIG_MISMATCH)
        instruments = state["instruments"]
        entries = state["events"]
        order = state["event_order"]
        if (
            not isinstance(instruments, dict)
            or not isinstance(entries, list)
            or not isinstance(order, list)
        ):
            raise SnapshotError(SNAPSHOT_CORRUPT)

        replayer = cls()
        engines: dict[str, Engine] = {}
        last_sequence: dict[str, int] = {}
        for symbol, instrument in instruments.items():
            if not isinstance(symbol, str) or not isinstance(instrument, dict):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            last = instrument["last_sequence"]
            if not _is_int(last) or last < 0:
                raise SnapshotError(SNAPSHOT_CORRUPT)
            engines[symbol] = Engine.from_state(instrument["engine"])
            last_sequence[symbol] = last
        replayer._engines = engines
        replayer._last_sequence = last_sequence

        seen: dict[str, _SeenEvent] = {}
        sequences: dict[str, set[int]] = {symbol: set() for symbol in engines}
        for entry in entries:
            if not isinstance(entry, dict):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            event_id = entry["event_id"]
            symbol = entry["symbol"]
            seq = entry["sequence"]
            content_digest = entry["content_digest"]
            stored_result = entry["result"]
            if (
                not _is_non_empty_str(event_id)
                or not isinstance(symbol, str)
                or not _is_int(seq)
                or not isinstance(content_digest, str)
                or not isinstance(stored_result, dict)
                or symbol not in engines
                or event_id in seen
            ):
                raise SnapshotError(SNAPSHOT_CORRUPT)
            sequences.setdefault(symbol, set()).add(seq)
            seen[event_id] = _SeenEvent(symbol, seq, content_digest, stored_result)

        if sorted(order) != sorted(seen) or any(
            not isinstance(event_id, str) for event_id in order
        ):
            raise SnapshotError(SNAPSHOT_CORRUPT)
        for symbol, seqs in sequences.items():
            if seqs != set(range(1, last_sequence[symbol] + 1)):
                raise SnapshotError(SNAPSHOT_CORRUPT)

        replayer._seen = seen
        replayer._order = list(order)
        return replayer


def format_version() -> str:
    """Return the snapshot format version supported by this implementation."""
    return FORMAT_VERSION


def _canonical_config() -> dict[str, Any]:
    return json.loads(json.dumps(_CONFIG, ensure_ascii=False))


# --- Module-level convenience entry points ----------------------------------


def replay_events(events: Any, *, snapshot: Any = None) -> dict[str, Any]:
    """Replay one ordered batch of envelopes in a single public call.

    With *snapshot* omitted the replay starts from an empty state; otherwise the
    snapshot is validated and restored first (raising :class:`SnapshotError`).
    Different symbols keep independent sequences and books, while input order
    within and across symbols is preserved exactly.
    """
    replayer = (
        EventReplayer()
        if snapshot is None
        else EventReplayer.from_snapshot(snapshot)
    )
    return replayer.replay(events)


def restore_snapshot(snapshot: Any) -> EventReplayer:
    """Validate and restore a snapshot, returning a ready :class:`EventReplayer`."""
    return EventReplayer.from_snapshot(snapshot)

