class _Ordered:
    """Total, type-stable ordering wrapper for canonical JSON key sorting."""

    __slots__ = ("value")

    def __init__(self, value: Any) -> None:
        self.value = value

    def _rank(self) -> tuple[int, Any]:
        value = self.value
        if value is None:
            return (0, 0)
        if isinstance(value, bool):
            return (1, int(value))
        if isinstance(value, int):
            return (2, value)
        if isinstance(value, float):
            return (3, value)
        if isinstance(value, str):
            return (4, value)
        if isinstance(value, list):
            return (5, None)
        if isinstance(value, dict):
            return (6, None)
        return (7, repr(value))

    def __lt__(self, other: _Ordered) -> bool:
        rank = self._rank()
        other_rank = other._rank()
        if rank[0] != other_rank[0]:
            return rank[0] < other_rank[0]
        if rank[0] in (5, 6):
            # Containers of the same shape never compare directly; fall back to
            # their own canonical bytes instead of recursing unordered.
            return canonical_dumps(self.value) < canonical_dumps(other.value)
        return rank[1] < other_rank[1]


def canonical_dumps(obj: Any) -> bytes:
    """Serialize *obj* to deterministic, byte-comparable canonical JSON.

    Object keys are sorted by a type-stable total order, compact separators
    are used and non-ASCII characters pass through unescaped, matching the
    baseline replay output.  Identical content always yields identical bytes
    regardless of insertion order.
    """
    return json.dumps(
        _canonicalize(obj),
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")


def _canonicalize(obj: Any) -> Any:
    if obj is None or isinstance(obj, (str, bool, int)):
        return obj
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise CanonicalError("non-finite floats are not canonicalizable")
        return obj
    if isinstance(obj, dict):
        return [
            [_canonicalize(ordered_key.value), _canonicalize(value)]
            for ordered_key, value in sorted(
                ((_Ordered(k), v) for k, v in obj.items()),
                key=lambda item: item[0],
            )
        ]
    if isinstance(obj, (list, tuple)):
        return [_canonicalize(item) for item in obj]
    raise CanonicalError(f"object is not JSON-compatible: {type(obj)!r}")

