# pyflakes-style unused import scan via compile + AST
import ast, sys
for f in ("order_book_engine/event_replay.py","order_book_engine/engine.py","order_book_engine/__init__.py"):
    src=open(f).read()
    tree=ast.parse(src)
    imported=set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names: imported.add(a.asname or a.name)
        elif isinstance(node, ast.Import):
            for a in node.names: imported.add((a.asname or a.name).split(".")[0])
    used={n.id for n in ast.walk(tree) if isinstance(n,ast.Name)}
    attr_roots={n.value.id for n in ast.walk(tree) if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name)}
    unused=[i for i in imported if i not in used and i not in attr_roots and i!="annotations"]
    print(f, "unused:", unused)
